-- Generated by `pnpm --filter @carbon/database authz migration` from packages/database/src/authz. Do not edit.

-- Ships these rules to databases where `authz sync` does not run after migrations yet.

CREATE OR REPLACE FUNCTION public.sync_load_work_center_operation(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_operation != 'INSERT' THEN RETURN; END IF;

  -- Only a starting event loads: an event inserted with an endTime (an ERP
  -- entry, an assigned interval, a closed sensor run) never does.
  IF (p_new->>'endTime') IS NOT NULL OR (p_new->>'workCenterId') IS NULL THEN
    RETURN;
  END IF;

  -- This runs as the owner (the dispatchers are SECURITY DEFINER), and the
  -- event's workCenterId and jobOperationId are single-column FKs: an event
  -- may only load its OWN company's operation onto its own company's work
  -- center, or another company's sensor time would land on it.
  UPDATE "workCenter"
  SET "loadedJobOperationId" = p_new->>'jobOperationId',
      "loadedAt" = (p_new->>'startTime')::timestamptz
  WHERE "id" = p_new->>'workCenterId'
    AND "companyId" = p_new->>'companyId'
    AND ("loadedAt" IS NULL OR "loadedAt" <= (p_new->>'startTime')::timestamptz)
    AND "loadedJobOperationId" IS DISTINCT FROM p_new->>'jobOperationId'
    AND EXISTS (
      SELECT 1 FROM "jobOperation"
      WHERE "id" = p_new->>'jobOperationId'
        AND "companyId" = p_new->>'companyId'
    );
  IF NOT FOUND THEN RETURN; END IF;

  -- The history: the previous load ends where this one starts. The OEE sync
  -- gives a run to the operation loaded when it started.
  UPDATE "workCenterLoad"
  SET "unloadedAt" = (p_new->>'startTime')::timestamptz
  WHERE "workCenterId" = p_new->>'workCenterId'
    AND "companyId" = p_new->>'companyId'
    AND "unloadedAt" IS NULL;

  INSERT INTO "workCenterLoad" ("companyId", "workCenterId", "jobOperationId", "loadedAt")
  VALUES (
    p_new->>'companyId',
    p_new->>'workCenterId',
    p_new->>'jobOperationId',
    (p_new->>'startTime')::timestamptz
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_unload_work_center_operation(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- A deleted operation unloads too: the pointer has no foreign key, because
  -- one would make PostgREST embeds of workCenter from jobOperation ambiguous.
  IF p_operation = 'DELETE' THEN
    UPDATE "workCenter"
    SET "loadedJobOperationId" = NULL,
        "loadedAt" = NULL
    WHERE "loadedJobOperationId" = p_old->>'id';
    UPDATE "workCenterLoad"
    SET "unloadedAt" = NOW()
    WHERE "jobOperationId" = p_old->>'id'
      AND "companyId" = p_old->>'companyId'
      AND "unloadedAt" IS NULL;
    RETURN;
  END IF;

  -- An operation moved to another work center leaves the old one: its sensor
  -- time there is no longer this operation's.
  IF p_operation = 'UPDATE'
     AND (p_old->>'workCenterId') IS DISTINCT FROM (p_new->>'workCenterId') THEN
    UPDATE "workCenter"
    SET "loadedJobOperationId" = NULL,
        "loadedAt" = NULL
    WHERE "id" = p_old->>'workCenterId'
      AND "companyId" = p_old->>'companyId'
      AND "loadedJobOperationId" = p_new->>'id';
    UPDATE "workCenterLoad"
    SET "unloadedAt" = NOW()
    WHERE "workCenterId" = p_old->>'workCenterId'
      AND "companyId" = p_old->>'companyId'
      AND "jobOperationId" = p_new->>'id'
      AND "unloadedAt" IS NULL;
  END IF;

  IF p_operation != 'UPDATE' THEN RETURN; END IF;
  IF (p_new->>'status') NOT IN ('Done', 'Canceled') THEN RETURN; END IF;
  IF (p_old->>'status') = (p_new->>'status') THEN RETURN; END IF;

  UPDATE "workCenter"
  SET "loadedJobOperationId" = NULL,
      "loadedAt" = NULL
  WHERE "loadedJobOperationId" = p_new->>'id';
  UPDATE "workCenterLoad"
  SET "unloadedAt" = NOW()
  WHERE "jobOperationId" = p_new->>'id'
    AND "companyId" = p_new->>'companyId'
    AND "unloadedAt" IS NULL;
END;
$function$;

-- workCenterLoad
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'workCenterLoad' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'workCenterLoad');
  END LOOP;
END
$authz$;
ALTER TABLE public."workCenterLoad" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "SELECT" ON "public"."workCenterLoad" FOR SELECT USING ("companyId" = ANY ((SELECT get_companies_with_employee_role())::text[]));
